#!/usr/bin/env python3
"""Actual CombatLog DISCONNECT callback with service doubles. Reflective tag setup, not AFTER_DAMAGE PvP tagging coverage."""
from pathlib import Path
import subprocess,tempfile,os
R=Path(os.environ.get('MESHAC_TEST_TREE',Path(__file__).resolve().parents[1]))
with tempfile.TemporaryDirectory(prefix='combatlog-monitor-') as d:
 p=Path(d)
 def put(n,s):
  f=p/n;f.parent.mkdir(parents=True,exist_ok=True);f.write_text(s)
 put('dev/meshac/CombatLog.java',(R/'src/main/java/dev/meshac/CombatLog.java').read_text())
 put('dev/meshac/Config.java','''package dev.meshac;public class Config {static Config C=new Config();static boolean monitor;public static Config get(){return C;}public boolean monitor(){return monitor;}public boolean combatLog(){return true;}public int combatLogSeconds(){return 30;}}''')
 put('dev/meshac/Cases.java','''package dev.meshac;import java.util.*;public class Cases{static int n;public static void add(String a,UUID b,String c,String d,String e,int f,List<String> g){n++;}}''')
 put('dev/meshac/Meshac.java','''package dev.meshac;public class Meshac{static Logger LOG=new Logger();public static class Logger{static int would;public void info(String s,Object...v){if(s.contains("would have killed"))would++;}}}''')
 put('net/minecraft/server/level/ServerLevel.java','package net.minecraft.server.level;public class ServerLevel{}')
 put('net/minecraft/server/level/ServerPlayer.java','''package net.minecraft.server.level;import java.util.*;public class ServerPlayer{UUID id=UUID.randomUUID();public UUID getUUID(){return id;}public boolean isCreative(){return false;}public boolean isSpectator(){return false;}public boolean isAlive(){return true;}public record Profile(String name){}public Profile getGameProfile(){return new Profile("witness");}public Object level(){return new ServerLevel();}public int kills;public void kill(ServerLevel l){kills++;}}''')
 put('net/minecraft/network/chat/Component.java','package net.minecraft.network.chat;public class Component{public static Object literal(String s){return s;}}')
 put('net/fabricmc/fabric/api/entity/event/v1/ServerLivingEntityEvents.java','''package net.fabricmc.fabric.api.entity.event.v1;public class ServerLivingEntityEvents{public interface Damage{void call(Object e,Source s,float b,float d,boolean blocked);}public interface Death{void call(Object e,Source s);}public static class Source{public Object getEntity(){return null;}}public static class D{public void register(Damage f){}}public static class X{public void register(Death f){}}public static D AFTER_DAMAGE=new D();public static X AFTER_DEATH=new X();}''')
 put('net/fabricmc/fabric/api/networking/v1/ServerPlayConnectionEvents.java','''package net.fabricmc.fabric.api.networking.v1;import net.minecraft.server.level.ServerPlayer;public class ServerPlayConnectionEvents{public interface Disc{void call(Handler h,Server s);}public static class Handler{public ServerPlayer player;public Handler(ServerPlayer p){player=p;}}public static class Server{public int broadcasts;public boolean isRunning(){return true;}public Server getPlayerList(){return this;}public void broadcastSystemMessage(Object c,boolean b){broadcasts++;}}public static class D{public Disc callback;public void register(Disc c){callback=c;}}public static D DISCONNECT=new D();}''')
 put('dev/meshac/CombatLogMonitorWitness.java','''package dev.meshac;import java.lang.reflect.*;import net.minecraft.server.level.ServerPlayer;import net.fabricmc.fabric.api.networking.v1.ServerPlayConnectionEvents;public class CombatLogMonitorWitness{static void ok(boolean x,String s){if(!x)throw new AssertionError(s);}public static void main(String[]a)throws Exception{CombatLog.init();Method tag=CombatLog.class.getDeclaredMethod("tag",ServerPlayer.class);tag.setAccessible(true);var server=new ServerPlayConnectionEvents.Server();var mon=new ServerPlayer();Config.monitor=true;tag.invoke(null,mon);ServerPlayConnectionEvents.DISCONNECT.callback.call(new ServerPlayConnectionEvents.Handler(mon),server);ok(Meshac.Logger.would==1,"missing tagged-disconnect trigger witness");ok(mon.kills==0&&Cases.n==0&&server.broadcasts==0,"monitor punishment");Config.monitor=false;ServerPlayConnectionEvents.DISCONNECT.callback.call(new ServerPlayConnectionEvents.Handler(mon),server);ok(mon.kills==0,"monitor disconnect tag was not consumed");var en=new ServerPlayer();tag.invoke(null,en);ServerPlayConnectionEvents.DISCONNECT.callback.call(new ServerPlayConnectionEvents.Handler(en),server);ok(en.kills==1&&Cases.n==1&&server.broadcasts==1,"missing enforced positive control");System.out.println("COMBATLOG_MONITOR PASS trigger=1 kills=0 cases=0 broadcasts=0; ENFORCE PASS kills=1 cases=1 broadcasts=1");}}''')
 subprocess.run(['javac','-J-Xmx128m','-d',d,*map(str,p.rglob('*.java'))],check=True)
 subprocess.run(['java','-Xmx128m','-cp',d,'dev.meshac.CombatLogMonitorWitness'],check=True)
